        preg_match_all ('#<h3>Mount Point /(.*?).mp3</h3>#si', $select_data, $content_sel, PREG_PATTERN_ORDER) ? : '';
        $all=count($content[1]);
        if ($all)
        {
            for ($i=0; $i<$all; $i++)
            {
                $template->assign_block_vars('select_radio', array(
                    'NAME'   => $content[1][$i],
                    'SELECT' => $content_sel[1][$i],
                ));
            }
        }
        $template -> assign_vars(array(
            'RADIO_ON' => true,
        ));
